import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _bbox_from_relationship_ids(block_map: Dict[str, Dict[str, Any]], relationship_ids: List[str]) -> Optional[Dict[str, float]]:
    xs = []
    ys = []
    xe = []
    ye = []

    for rid in relationship_ids:
        block = block_map.get(rid)
        if not block:
            continue
        geometry = block.get("Geometry") or {}
        bbox = geometry.get("BoundingBox") or {}
        left = bbox.get("Left")
        top = bbox.get("Top")
        width = bbox.get("Width")
        height = bbox.get("Height")
        if None in (left, top, width, height):
            continue
        xs.append(float(left))
        ys.append(float(top))
        xe.append(float(left) + float(width))
        ye.append(float(top) + float(height))

    if not xs:
        return None

    return {
        "left": min(xs),
        "top": min(ys),
        "width": max(xe) - min(xs),
        "height": max(ye) - min(ys),
    }


def _text_from_children(block_map: Dict[str, Dict[str, Any]], block: Dict[str, Any]) -> str:
    text_parts = []
    for rel in block.get("Relationships", []) or []:
        if rel.get("Type") != "CHILD":
            continue
        for cid in rel.get("Ids", []) or []:
            child = block_map.get(cid)
            if not child:
                continue
            if child.get("BlockType") == "WORD":
                text_parts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    text_parts.append("X")
    return " ".join(t for t in text_parts if t).strip()


def extract_table_cells_and_rows(document_bytes: bytes, aws_region: Optional[str] = None) -> Dict[str, Any]:
    """
    Extracts table cells and row structure from a document using Amazon Textract.

    Returns a dictionary with:
      - tables: list of tables, each with rows and cells
      - raw_blocks: Textract blocks for reference
    """
    textract = boto3.client("textract", region_name=aws_region)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Amazon Textract analyze_document failed: {exc}") from exc

    blocks = response.get("Blocks", []) or []
    block_map: Dict[str, Dict[str, Any]] = {b["Id"]: b for b in blocks if "Id" in b}

    tables_output: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table = {
            "id": block.get("Id"),
            "bbox": block.get("Geometry", {}).get("BoundingBox", {}),
            "rows": [],
        }

        cell_blocks = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for cid in rel.get("Ids", []) or []:
                    child = block_map.get(cid)
                    if child and child.get("BlockType") == "CELL":
                        cell_blocks.append(child)

        rows: Dict[int, List[Dict[str, Any]]] = {}
        for cell in cell_blocks:
            row_index = int(cell.get("RowIndex", 0) or 0)
            col_index = int(cell.get("ColumnIndex", 0) or 0)
            cell_entry = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": int(cell.get("RowSpan", 1) or 1),
                "column_span": int(cell.get("ColumnSpan", 1) or 1),
                "text": _text_from_children(block_map, cell),
                "bbox": cell.get("Geometry", {}).get("BoundingBox", {}),
                "confidence": cell.get("Confidence"),
                "is_header": cell.get("EntityTypes", []) and "COLUMN_HEADER" in (cell.get("EntityTypes") or []),
            }
            rows.setdefault(row_index, []).append(cell_entry)

        for row_index in sorted(rows.keys()):
            row_cells = sorted(rows[row_index], key=lambda c: (c["column_index"], c["row_index"]))
            table["rows"].append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                }
            )

        tables_output.append(table)

    return {
        "tables": tables_output,
        "raw_blocks": blocks,
    }
